import csv

# Open the CSV file for reading
def main():
    total_sales = 0  
    with open('data.csv', newline='') as csvfile:  
        reader = csv.DictReader(csvfile)  
        for row in reader:  
            try:
                sale = float(row['sales'])  
                total_sales += sale  
            except (ValueError, KeyError):
                continue
    print(f"Total sales: {total_sales}")  

if __name__ == "__main__":
    main()

